def encode(message):
    vowels = {'a', 'e', 'i', 'o', 'u'}
    result = []
    for char in message:
        if char.isalpha():
            if char.lower() in vowels:
                # Replace vowel with the letter two places ahead
                vowel_index = vowels.index(char.lower())
                new_vowel = chr(ord('a') + vowel_index + 2)
                result.append(new_vowel.lower() if char.lower() in vowels else char)
            else:
                result.append(char)
        else:
            result.append(char)
    return ''.join(result)

