def minPath(grid, k):
    from collections import deque

    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[False] * N for _ in range(N)]
    queue = deque()

    # Initialize the queue with all cells that can be the starting point
    for i in range(N):
        for j in range(N):
            if not visited[i][j]:
                queue.append((i, j, [grid[i][j]]))
                visited[i][j] = True

    # Use BFS to find the minimum path
    while queue:
        current = queue.popleft()
        current_pos = current[0], current[1]
        current_path = current[2]

        if len(current_path) == k:
            if len(current_path) == k:
                return current_path

        for dx, dy in directions:
            nx, ny = current_pos[0] + dx, current_pos[1] + dy
            if 0 <= nx < N and 0 <= ny < N and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny, current_path + [grid[nx][ny]]))

    return []

def tri(n):
    """Return the first n + 1 numbers of the Tribonacci sequence."""
    if n == 0:
        return [0]
    if n == 1:
        return [3]
    tri_list = [3, 2]
    for i in range(2, n + 1):
        if i % 2 == 0:
            tri_list.append(1 + i // 2)
        else:
            tri_list.append(tri_list[-1] + tri_list[-2] + tri_list[-3])
    return tri_list

